def fizz_buzz(n: int) -> int:
    count = 0
    for i in range(1, n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

from typing import List

def triples_sum_to_zero(l: List[int]) -> bool:
    l.sort()  # Sort the list to make it easier to find triplets
    n = len(l)
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    return False

