def pluck(arr: List[int]) -> List[int]:
    if not arr:
        return []

    smallest_even = float('inf')
    smallest_index = -1

    for i, node in enumerate(arr):
        if node % 2 == 0 and node < smallest_even:
            smallest_even = node
            smallest_index = i

    return [smallest_even, smallest_index] if smallest_index != -1 else []

